const IDX = new Map(CUR_EN.map((s, i) => [s.toLowerCase(), i]));
const cache = new Map<string, string>();

/** The catalogue name in the active language (unknown / custom names come back unchanged). */
export function curLabel(text: string): string {
  const loc = hubLocale();
  const tr = CUR_LOCALE[loc];
  if (!tr || !text) return text;
  const key = loc + "\u0000" + text;
  const hit = cache.get(key);
  if (hit !== undefined) return hit;
  const out = text.split(" \u2013 ").map((p) => {
    const t = p.trim();
    const i = IDX.get(t.toLowerCase());
    return i === undefined || !tr[i] ? p : tr[i]!;
  }).join(" \u2013 ");
  cache.set(key, out);
  return out;
}
